    quietmode: 0
  "2":
    id: "2"
    taskid: 63dc8892-db0a-46d4-8dc6-1517a4033576
    type: regular
    task:
      id: 63dc8892-db0a-46d4-8dc6-1517a4033576
      version: -1
      name: Run the Active Directory ACL Scanner
      description: "Identify compromised accounts. \nAttackers will aim for a high privileged domain account that will enable them to spread and deliver the malicious payload to as many endpoints/servers as possible. \n\nTo simplify the work of creating and documenting the delegation model in Active Directory, a tool with a GUI in PowerShell is provided below.\nThis tool creates reports of the access control list for all of your Active Directory objects. With these reports, you can see what/where, and when permissions have been set.\n\nTo run the script, the minimum requirements are: PowerShell 2.0 and Windows 7/Windows Server 2008 (Windows Server 2003 can be used, but it will have limited functionality).\n\nEnable unsigned scripting in PowerShell by using the command:\nSet-ExecutionPolicy Unrestricted.\n\nIf you are not a local admin and cannot set it on your machine, you can set it for your profile:\nSet-ExecutionPolicy Unrestricted - Scope CurrentUser.\nYou do not need Powershell Module for Active Directory.\n\nMicrosoft article about Active Directory forensics with ACL Scanner:\nhttps://docs.microsoft.com/en-us/archive/blogs/pfesweplat/forensics-active-directory-acl-investigation\n\nMicrosoft article about AD ACL scanner tool:\nhttps://docs.microsoft.com/en-us/archive/blogs/pfesweplat/take-control-over-ad-permissions-and-the-ad-acl-scanner-tool\n\nAD ACL Scanner Github project:\nhttps://github.com/canix1/ADACLScanner\n"
      type: regular
      iscommand: false
      brand: ""
